  function chestJewel(it) {
    if (it.kind === "nugget") return `<path d="M84 150 Q100 172 116 150" stroke="#e0b03a" stroke-width="1.6" fill="none"/><path d="M95 166 L100 160 L106 163 L107 170 L101 175 L94 172 Z" fill="#f2c230" stroke="#b8860b" stroke-width="1"/>${tw(104,164,3,"#fff",0,1.8)}`;
    if (it.kind === "equality") return `<circle cx="64" cy="180" r="10" fill="#f4f1ea" stroke="#2a2a2a" stroke-width="1.5"/><circle cx="64" cy="180" r="7.5" fill="#3a6fd8"/><rect x="59" y="176" width="10" height="2.4" fill="#fff"/><rect x="59" y="181.5" width="10" height="2.4" fill="#fff"/>`;
    return "";
  }

  function clean(eq) {
    const e = Object.assign({}, DEFAULT);
    if (eq) for (const k of SLOTS) if (eq[k] && byId[eq[k]] && byId[eq[k]].slot === k) e[k] = eq[k];
    return e;
  }
  function avatarSVG(eq) {
    const e = clean(eq), id = "av" + (RID++);
    const it = k => byId[e[k]];
    const sk = it("skin").color, hcIt = it("haircolor"), hc = hcIt.color, top = it("top").color;
    const defs = `<linearGradient id="${id}sk" x1="0" x2="1"><stop offset="0" stop-color="${lt(sk, .08)}"/><stop offset=".65" stop-color="${sk}"/><stop offset="1" stop-color="${dk(sk, .14)}"/></linearGradient>
      <linearGradient id="${id}t" x1="0" x2="1"><stop offset="0" stop-color="${lt(top, .12)}"/><stop offset=".6" stop-color="${top}"/><stop offset="1" stop-color="${dk(top, .25)}"/></linearGradient>
      <radialGradient id="${id}bl" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#e86a7a" stop-opacity=".28"/><stop offset="1" stop-color="#e86a7a" stop-opacity="0"/></radialGradient>` + hairDefs(hcIt, id);
    const fancy = !!hcIt.fx;
    const hd = fancy ? dk(hc, .45) : dk(hc, .4), hl = fancy ? "#ffffff" : lt(hc, .35);
    const style = it("hairstyle").kind;
    const hair = hairShapes(style, `fill="url(#${id}h)"`, hd, hl);
    let glowBack = "", glowFront = "";
    if (hcIt.fx === "neon") {
      const g = hairShapes(style, `fill="#3ff0ff"`, "#3ff0ff", "#3ff0ff");
      const wrap = x => `<g filter="url(#${id}glow)" opacity=".8">${x}${anim("opacity", ".35;.9;.35", 1.8)}</g>`;
      glowBack = wrap(g.back); glowFront = wrap(g.front);
    }
    const browC = fancy ? "#4a2f22" : dk(hc, .25);
    const H = s => `<g transform="translate(100 96) scale(1.15)">${s}</g>`;
    let s = `<defs>${defs}</defs>` + background(it("bg"), id) + auraSVG(it("aura"), id);
    s += H(glowBack + hair.back);
    s += topSVG(it("top"), id, sk) + chestJewel(it("jewellery"));
    s += H(face(sk, it("eyes"), e.lashes === "lash-on", browC, id) + facePaint(it("face"), sk) + jewellery(it("jewellery")) + glowFront + hair.front + hairExtras(hcIt, style) + glassesSVG(it("glasses"), id) + hatSVG(it("hat"), id));
    s += extraSVG(it("extra"));
    return `<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:auto">${s}</svg>`;
  }
  function rarity(price) {
    if (!price) return { name: "Free", color: "#7dffb0" };
    if (price < 100) return { name: "Común", color: "#c9d2e3" };
    if (price < 300) return { name: "Raro", color: "#5aa9ff" };
    if (price < 700) return { name: "Épico", color: "#c07cff" };
    return { name: "Legendario", color: "#f2c230" };
  }
  function inSeason(item) { return !item.months || item.months.indexOf(new Date().getMonth() + 1) >= 0; }
  function levelOf(xp) { let l = 0; LEVEL_XP.forEach(t => { if (xp >= t) l++; }); return l; }
  function levelInfo(xp) {
    const l = levelOf(xp), cur = LEVEL_XP[l - 1] || 0, next = LEVEL_XP[l];
    return { level: l, name: LEVEL_NAMES[l] || "Legend+", xp: xp, cur: cur, next: next, pct: next ? Math.round((xp - cur) / (next - cur) * 100) : 100 };
  }

  function myAvatar() { const s = getSession(); return avatarSVG(s && s.state ? s.state.equipped : null); }
  window.E8 = { CATALOG: CATALOG, SLOTS: SLOTS, TABS: TABS, SLOTNAME: SLOTNAME, DEFAULT: DEFAULT, LEVEL_XP: LEVEL_XP, getSession: getSession, login: login, setPin: setPin, logout: logout, call: call, api: api, errText: errText, reportInto: reportInto, avatarSVG: avatarSVG, myAvatar: myAvatar, clean: clean, rarity: rarity, inSeason: inSeason, levelInfo: levelInfo, item: id => byId[id], ACTIVE_UNITS: ACTIVE_UNITS, available: i => !i.unit || ACTIVE_UNITS.indexOf(i.unit) >= 0, online: () => !!API_URL && API_URL.indexOf("/*") !== 0 };
